```python
class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        result = max(nums)
        if result <= 0:
            return result

        val = 0
        for i in range(len(nums)):
            val += nums[i]
            if val < 0:
                val = 0
            result = max(result, val)
        return result
